function countNonDecreasingSubarrays(nums, k) {
  const n = nums.length;
  const nextAtLeast = new Array(n).fill(n);
  const takeOver = Array.from({ length: n }, () => []);
  const stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && nums[stack[stack.length - 1]] <= nums[i]) {
      nextAtLeast[stack.pop()] = i;
    }
    if (stack.length > 0) {
      takeOver[stack[stack.length - 1]].push(i);
    }
    stack.push(i);
  }

  const maxQueue = [];
  let head = 0;
  let left = 0;
  let cost = 0;
  let count = 0;
  for (let right = 0; right < n; right++) {
    while (maxQueue.length > head && nums[maxQueue[maxQueue.length - 1]] <= nums[right]) {
      maxQueue.pop();
    }
    maxQueue.push(right);
    cost += nums[maxQueue[head]] - nums[right];
    while (cost > k) {
      for (const i of takeOver[left]) {
        if (i > right) break;
        cost -= (nums[left] - nums[i]) * (Math.min(nextAtLeast[i], right + 1) - i);
      }
      left++;
      if (maxQueue[head] < left) head++;
    }
    count += right - left + 1;
  }
  return count;
}

