function countNonDecreasingSubarrays(nums, k) {
  // Fix each subarray greedily: every element that dips below the one before it is raised to match it.
  let count = 0;
  for (let start = 0; start < nums.length; start++) {
    let last = nums[start], spent = 0;
    for (let end = start; end < nums.length; end++) {
      if (nums[end] < last) spent += last - nums[end];
      else last = nums[end];
      if (spent <= k) count++;
    }
  }
  return count;
}

