function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 : 1 + pick(8);
  // Values come from a narrow or a wide range; some arrays are sorted up or down.
  const top = large ? [10, 1000, 1000000000][pick(3)] : [3, 10, 1000000000][pick(3)];
  const nums = Array.from({ length: n }, () => 1 + pick(top));
  const order = pick(5);
  if (order === 1) nums.sort((a, b) => a - b);
  if (order === 2) nums.sort((a, b) => b - a);
  // k is tiny, comparable to the values, or the largest allowed.
  const choice = pick(3);
  const k = choice === 0 ? 1 + pick(3) : choice === 1 ? 1 + pick(top * (large ? 50 : 3)) : 1000000000;
  return [nums, Math.min(k, 1000000000)];
}
